with exploded as (select id, created_at, coupon_codes, line.product_id, line.qty, line.price, line.promo from carts lateral view outer explode(items) e as line) select product_id, promo, round(product_id / sum(product_id) over (partition by promo), 4) as product_id_share, cume_dist() over (partition by promo order by price) as price_cume_dist, round(qty / sum(qty) over (partition by promo), 4) as qty_share, max(price) over (partition by promo) as promo_max_price, max(price) over w_part as price_max_30m from exploded where created_at >= '2024-04-01' window w_part as (partition by promo order by cast(created_at as bigint) range between 1800 preceding and current row)
